declare(strict_types=1);
namespace Sexogate;
final class SourceApi
{
    private \Closure $fetch;
    public function __construct(private Database $db,private Config $config,?callable $fetch=null){$this->fetch=\Closure::fromCallable($fetch??[new SupplierApiHttp(),'fetch']);}
    public function listing(Principal $actor):array
    {$actor->require('catalog');return $this->db->all('SELECT c.*,r.status run_status,r.resource,r.page,r.category_total,r.product_total FROM source_api_connections c LEFT JOIN source_api_runs r ON r.id=c.last_run_id ORDER BY c.vendor');}
    public function run(string $id,Principal $actor):array
    {$actor->require('catalog');$run=$this->db->one('SELECT * FROM source_api_runs WHERE id=?',[$id]);RuleViolation::ensure($run,'SOURCE_API_NOT_FOUND','API çalıştırması bulunamadı.',404);return $run;}
    private function connection(string $vendor):array
    {$row=$this->db->one('SELECT * FROM source_api_connections WHERE vendor=? FOR UPDATE',[$vendor]);RuleViolation::ensure($row,'SOURCE_API_UNKNOWN','Tedarikçi seçimini kontrol edin.',400);return $row;}
    private function enqueue(string $run,string $resource,int $page):void
    {$this->db->execute("INSERT INTO jobs(id,type,payload,dedupe_key,max_attempts,available_at) VALUES(?,'source.api.page',?,?,3,DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND)) ON DUPLICATE KEY UPDATE dedupe_key=dedupe_key",[Database::id(),$this->config->json(['runId'=>$run,'resource'=>$resource,'page'=>$page]),'source-api:'.$run.':'.$resource.':'.$page]);}
    private function begin(array $connection,string $actor):array
    {
        if($connection['active_run_id'])return ['id'=>$connection['active_run_id'],'existing'=>true];$id=Database::id();$batch=Database::id();$this->db->execute("INSERT INTO source_catalog_batches(id,vendor,file_sha256,created_by,status,source_method) VALUES(?,? ,?,?,'collecting','public-api')",[$batch,$connection['vendor'],str_repeat('0',64),$actor]);$this->db->execute('INSERT INTO source_api_runs(id,vendor,batch_id,requested_by) VALUES(?,?,?,?)',[$id,$connection['vendor'],$batch,$actor]);$this->db->execute('UPDATE source_api_connections SET active_run_id=?,last_run_id=?,last_attempt_at=CURRENT_TIMESTAMP(3),last_error=NULL WHERE vendor=?',[$id,$id,$connection['vendor']]);$this->enqueue($id,'categories',1);return ['id'=>$id,'batchId'=>$batch];
    }
    public function start(string $vendor,string $key,Principal $actor):array
    {$actor->require('catalog',true);RuleViolation::ensure($vendor==='xshopum','SOURCE_API_CREDENTIALS_REQUIRED','Bu tedarikçi için onaylı bayi API/XML erişimi gerekir.',409);return (new Audit($this->db))->command($actor,$key,['source-api-start',$vendor],function()use($vendor,$actor){$row=$this->connection($vendor);RuleViolation::ensure($row['active_run_id']||$row['last_attempt_at']===null||strtotime($row['last_attempt_at'].' UTC')<=time()-60,'SOURCE_API_RATE_LIMIT','Bağlantı denemeleri arasında bir dakika bekleyin.',429);$result=$this->begin($row,$actor->id);(new Audit($this->db))->record($actor,'request','source_api',$result['id']);return $result;});}
    public function configure(string $vendor,bool $enabled,int $minutes,Principal $actor):array
    {$actor->require('catalog',true);RuleViolation::ensure($minutes>=60&&$minutes<=1440,'SOURCE_API_INTERVAL','Güncelleme aralığı 60–1440 dakika olmalıdır.',400);return $this->db->transaction(function()use($vendor,$enabled,$minutes,$actor){$row=$this->connection($vendor);RuleViolation::ensure(!$enabled||$vendor==='xshopum'&&$row['last_success_at']!==null&&$row['last_error']===null,'SOURCE_API_ACCESS_REQUIRED','Otomatik güncellemeden önce sunucudan başarılı API bağlantısı doğrulanmalıdır.');$this->db->execute('UPDATE source_api_connections SET enabled=?,poll_minutes=?,next_run_at=DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL ? MINUTE),updated_by=? WHERE vendor=?',[(int)$enabled,$minutes,$minutes,$actor->id,$vendor]);(new Audit($this->db))->record($actor,'configure','source_api',$vendor,['enabled'=>$enabled,'minutes'=>$minutes]);return ['enabled'=>$enabled];});}
    public function scheduleDue():int
    {foreach($this->db->all("SELECT * FROM source_api_runs WHERE status='running' AND started_at<DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 HOUR) LIMIT 10") as $run)$this->failure($run,'SOURCE_API_RUN_TIMEOUT',false);return $this->db->transaction(function(){$rows=$this->db->all('SELECT * FROM source_api_connections WHERE enabled=true AND active_run_id IS NULL AND next_run_at<=CURRENT_TIMESTAMP(3) ORDER BY vendor FOR UPDATE SKIP LOCKED');foreach($rows as $row)$this->begin($row,'source-api-scheduler');return count($rows);});}
    private function failure(array $run,string $code,bool $access):void
    {$this->db->transaction(function()use($run,$code,$access){$this->connection($run['vendor']);$r=$this->db->one('SELECT status FROM source_api_runs WHERE id=? FOR UPDATE',[$run['id']]);if(!$r||$r['status']!=='running')return;$this->db->execute('UPDATE source_api_runs SET status=?,last_error=?,completed_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$access?'access_required':'failed',$code,$run['id']]);$this->db->execute("UPDATE source_catalog_batches SET status='failed' WHERE id=?",[$run['batch_id']]);$this->db->execute('UPDATE source_api_connections SET active_run_id=NULL,enabled=IF(?,false,enabled),last_error=?,next_run_at=DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL poll_minutes MINUTE) WHERE vendor=?',[(int)$access,$code,$run['vendor']]);});}
    public function process(string $id,string $resource,int $page,int $attempt):void
    {
        SupplierApiHttp::endpoint($resource,$page);$run=$this->db->one('SELECT * FROM source_api_runs WHERE id=?',[$id]);RuleViolation::ensure($run,'SOURCE_API_NOT_FOUND','API çalıştırması bulunamadı.',404);if($run['status']!=='running'||$this->db->one('SELECT run_id FROM source_api_pages WHERE run_id=? AND resource=? AND page=?',[$id,$resource,$page]))return;RuleViolation::ensure($run['resource']===$resource&&(int)$run['page']===$page,'SOURCE_API_CURSOR','API sayfa sırası geçersiz.',409);
        try{
            $response=($this->fetch)($resource,$page);$status=$response['status'];if(in_array($status,[401,403],true)){$this->failure($run,'SOURCE_API_HTTP_'.$status,true);return;}RuleViolation::ensure($status===200,'SOURCE_API_HTTP_'.$status,'Tedarikçi API yanıtı başarılı değil.',503);$total=$response['total'];RuleViolation::ensure(is_int($total)&&$total>=0&&$total<=20000,'SOURCE_API_TOTAL','API toplam bilgisi doğrulanamadı.',503);try{$rows=json_decode($response['body'],true,32,JSON_THROW_ON_ERROR|JSON_BIGINT_AS_STRING);}catch(\Throwable){throw new RuleViolation('SOURCE_API_INVALID_JSON','API yanıtı JSON biçiminde değil.',503);}RuleViolation::ensure(is_array($rows)&&array_is_list($rows)&&count($rows)<=100,'SOURCE_API_FORMAT','API kayıt biçimi geçersiz.',503);$last=$page*100>=$total;RuleViolation::ensure(count($rows)===($last?max(0,$total-($page-1)*100):100),'SOURCE_API_COUNT_MISMATCH','API sayfa toplamı değişti; son başarılı katalog korunuyor.',503);$records=array_map(fn($row)=>$this->map($row,$resource,hash('sha256',$response['body'])),$rows);
            $this->db->transaction(function()use($run,$resource,$page,$total,$last,$records,$response){$this->connection($run['vendor']);$current=$this->db->one('SELECT * FROM source_api_runs WHERE id=? FOR UPDATE',[$run['id']]);if($current['status']!=='running'||$this->db->one('SELECT run_id FROM source_api_pages WHERE run_id=? AND resource=? AND page=?',[$run['id'],$resource,$page]))return;RuleViolation::ensure($current['resource']===$resource&&(int)$current['page']===$page,'SOURCE_API_CURSOR','API sayfa sırası değişti.',503);$column=$resource==='categories'?'category_total':'product_total';RuleViolation::ensure($current[$column]===null||(int)$current[$column]===$total,'SOURCE_API_TOTAL_CHANGED','Çekim sırasında kaynak toplamı değişti.',503);
                $this->db->one('SELECT id FROM source_catalog_batches WHERE id=? FOR UPDATE',[$run['batch_id']]);foreach($records as $r)$this->db->execute("INSERT INTO source_catalog_records(batch_id,source_key,kind,source_url,title,payload,metadata_state) VALUES(?,?,?,?,?,?,'parsed') ON DUPLICATE KEY UPDATE payload=VALUES(payload),title=VALUES(title)",[$run['batch_id'],hash('sha256',$r['sourceUrl']),$r['kind'],$r['sourceUrl'],$r['title'],$this->config->json($r)]);$this->db->execute('INSERT INTO source_api_pages(run_id,resource,page,sha256,row_count,total_count) VALUES(?,?,?,?,?,?)',[$run['id'],$resource,$page,hash('sha256',$response['body']),count($records),$total]);$this->db->execute('UPDATE source_api_runs SET '.$column.'=?,last_error=NULL WHERE id=?',[$total,$run['id']]);
                if(!$last){$this->db->execute('UPDATE source_api_runs SET page=page+1 WHERE id=?',[$run['id']]);$this->enqueue($run['id'],$resource,$page+1);return;}if($resource==='categories'){$this->db->execute("UPDATE source_api_runs SET resource='products',page=1 WHERE id=?",[$run['id']]);$this->enqueue($run['id'],'products',1);return;}
                $counts=$this->db->one("SELECT SUM(kind='product') products,SUM(kind='category') categories,COUNT(*) n FROM source_catalog_records WHERE batch_id=?",[$run['batch_id']]);RuleViolation::ensure($total>0&&(int)$counts['products']===$total&&(int)$counts['categories']===(int)$current['category_total'],'SOURCE_API_COUNT_MISMATCH','Tam katalog sayımı doğrulanamadı.',503);$hash=hash_init('sha256');foreach($this->db->all('SELECT payload FROM source_catalog_records WHERE batch_id=? ORDER BY source_key',[$run['batch_id']]) as $row)hash_update($hash,$row['payload']."\n");$this->db->execute("UPDATE source_catalog_batches SET status='complete',file_sha256=?,product_count=?,category_count=?,parsed_count=? WHERE id=?",[hash_final($hash),$total,(int)$counts['categories'],(int)$counts['n'],$run['batch_id']]);$this->db->execute("UPDATE source_api_runs SET status='complete',completed_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$run['id']]);$this->db->execute('UPDATE source_api_connections SET active_run_id=NULL,last_error=NULL,last_success_at=CURRENT_TIMESTAMP(3),next_run_at=DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL poll_minutes MINUTE) WHERE vendor=?',[$run['vendor']]);
            });
        }catch(\Throwable $e){$code=$e instanceof RuleViolation?$e->rule:'SOURCE_API_UNAVAILABLE';if($attempt>=3)$this->failure($run,$code,false);else $this->db->execute('UPDATE source_api_runs SET last_error=? WHERE id=? AND status=\'running\'',[$code,$id]);throw $e instanceof RuleViolation?$e:new RuleViolation('SOURCE_API_UNAVAILABLE','API güncellemesi tamamlanamadı.',503);}
    }
    private function map(array $row,string $resource,string $sha):array
    {
        $category=$resource==='categories';RuleViolation::ensure(is_int($row['id']??null)&&$row['id']>0&&is_string($row['name']??null)&&is_string($row['permalink']??null),'SOURCE_API_RECORD','Kaynak ürün kimliği geçersiz.',503);$text=fn($s)=>html_entity_decode(strip_tags((string)$s),ENT_QUOTES|ENT_HTML5,'UTF-8');$minor=null;$currency=null;$price=$row['prices']??[];if(!$category&&($price['currency_minor_unit']??null)===2&&in_array($price['currency_code']??'', ['TRY','EUR','USD','GBP'],true)&&is_string($price['price']??null)&&ctype_digit($price['price'])&&(int)$price['price']>0){$minor=Money::amount((int)$price['price']);$currency=$price['currency_code'];}$images=[];foreach($row['images']??[] as $image)if(is_array($image)&&is_string($image['src']??null))$images[]=$image['src'];if($category&&is_array($row['image']??null)&&is_string($row['image']['src']??null))$images[]=$row['image']['src'];
        $r=['vendor'=>'xshopum','kind'=>$category?'category':'product','sourceUrl'=>$row['permalink'],'title'=>$text($row['name']),'sku'=>$category?null:($row['sku']??null),'brand'=>is_string($row['brands'][0]['name']??null)?$text($row['brands'][0]['name']):null,'description'=>$category?'':mb_substr($text($row['description']??''),0,10000),'images'=>array_slice(array_values(array_unique($images)),0,30),'supplierQuantity'=>null,'quotedRetailMinor'=>$minor,'quotedCurrency'=>$currency,'publicInStock'=>is_bool($row['is_in_stock']??null)?$row['is_in_stock']:null,'metadataState'=>'parsed','sourceApiId'=>$row['id'],'parentSourceId'=>$row['parent']??null,'sourceMethod'=>'woocommerce-public-store-api','observedAt'=>gmdate('c'),'categories'=>$category?[]:($row['categories']??[]),'attributes'=>$row['attributes']??[],'variants'=>$row['variations']??[],'apiResponseSha256'=>$sha];(new SourceCatalog($this->db,$this->config))->validate($r,'xshopum');RuleViolation::ensure($r['title']!==''&&strlen($this->config->json($r))<=65536,'SOURCE_API_RECORD','Kaynak kayıt boyutunu kontrol edin.',503);return $r;
    }
}
